/**
 * Vybe shared domain model + HTTP API contract.
 * Single source of truth for server, web client and catalog generator.
 * All catalog content (artists, albums, songs, lyrics, art, audio) is ORIGINAL
 * and generated by scripts/generate_catalog.py.
 */

export type ID = string;

/** Artwork is a square image with a precomputed palette (used to tint pages, like album headers). */
export interface Artwork {
  url: string; // e.g. /media/art/al_001.webp  (square, 1000px)
  width: number;
  height: number;
  bgColor: string; // dominant color, hex "#rrggbb"
  textColor1: string; // primary text color that reads on bgColor
  textColor2: string; // secondary text
  textColor3: string; // tertiary / accent text
}

export interface Genre {
  id: ID; // "pop"
  name: string; // "Pop"
  color: string; // tile color for Browse/Search category grid
  artwork: Artwork;
}

export interface ArtistRef { id: ID; name: string }
export interface AlbumRef { id: ID; title: string }

export interface Artist {
  id: ID; // "ar_001"
  name: string;
  genreIds: ID[];
  bio: string;
  origin: string; // "Lisbon, Portugal"
  bornOrFormed: string; // "2016"
  artwork: Artwork; // portrait / hero image
  heroArtwork: Artwork; // wide banner-ish (still square file, displayed cropped)
  monthlyListeners: number;
}

export type AlbumType = 'album' | 'single' | 'ep' | 'compilation';

export interface Album {
  id: ID; // "al_001"
  title: string;
  artist: ArtistRef;
  type: AlbumType;
  genreId: ID;
  releaseDate: string; // ISO date
  copyright: string; // "℗ 2026 Vybe Originals"
  editorialNotes: string; // 1–3 sentences
  recordLabel: string;
  isExplicit: boolean;
  artwork: Artwork;
  trackIds: ID[];
  durationMs: number;
}

export interface LyricLine {
  startMs: number;
  endMs: number;
  text: string; // empty string = instrumental gap (render as "•••")
}

export interface Song {
  id: ID; // "so_0001"
  title: string;
  artist: ArtistRef;
  featuring: ArtistRef[];
  album: AlbumRef;
  genreId: ID;
  trackNumber: number;
  discNumber: number;
  durationMs: number;
  isExplicit: boolean;
  hasLyrics: boolean;
  audioUrl: string; // /api/stream/:songId (supports HTTP Range)
  artwork: Artwork; // same as album artwork
  releaseDate: string;
  bpm: number;
  mood: Mood;
  energy: number; // 0..1
  popularity: number; // 0..100 (drives Top Songs / charts)
  composer: string;
}

export type Mood = 'chill' | 'upbeat' | 'melancholy' | 'energetic' | 'romantic' | 'dreamy' | 'dark' | 'focus';

export type PlaylistKind = 'editorial' | 'personal-mix' | 'user';

export interface Playlist {
  id: ID; // "pl_ed_001" (editorial), "pl_mix_xxx", "pl_u_<uuid>" (user)
  kind: PlaylistKind;
  name: string;
  curatorName: string; // "Vybe Pop", or user's display name
  description: string;
  shortDescription: string; // "Today's biggest hits."
  artwork: Artwork;
  trackIds: ID[];
  durationMs: number;
  updatedAt: string; // ISO
  isPublic: boolean;
  ownerId?: ID; // user playlists only
}

export interface Station {
  id: ID; // "st_001"
  name: string; // "Vybe Hits"
  tagline: string;
  kind: 'live' | 'genre' | 'artist' | 'song';
  seedId?: ID; // genre/artist/song id it is based on
  artwork: Artwork;
}

/** Editorial "room" / category page grouping (e.g. Search category tiles, New page shelves). */
export interface Room {
  id: ID;
  title: string;
  genreId?: ID;
  items: ContentRef[];
}

export type ContentType = 'song' | 'album' | 'playlist' | 'artist' | 'station';
export interface ContentRef { type: ContentType; id: ID }

/** Hydrated shelf item returned by page endpoints. */
export type ContentItem =
  | { type: 'song'; data: Song }
  | { type: 'album'; data: Album }
  | { type: 'playlist'; data: Playlist }
  | { type: 'artist'; data: Artist }
  | { type: 'station'; data: Station };

export type ShelfLayout =
  | 'hero' // large editorial cards with eyebrow label (New page top)
  | 'grid-lockups' // horizontal scroller of square artwork lockups
  | 'song-list' // 3-column paged song chart rows (Best New Songs)
  | 'circle-artists' // circular artist avatars
  | 'tiles' // category tiles (search landing)
  | 'large-tiles'; // big mixes cards (Made For You)

export interface HeroCard {
  eyebrow: string; // "NEW ALBUM" / "UPDATED PLAYLIST"
  title: string;
  subtitle: string;
  caption: string; // text on the artwork
  item: ContentItem;
}

export interface Shelf {
  id: ID;
  title: string;
  subtitle?: string;
  layout: ShelfLayout;
  seeAllHref?: string;
  items: ContentItem[];
  heroCards?: HeroCard[]; // layout === 'hero'
}

export interface PageResponse { title: string; shelves: Shelf[] }

// ---------------- Users / library ----------------

export interface User {
  id: ID;
  email: string;
  displayName: string;
  avatarColor: string;
  createdAt: string;
}

export interface LibraryState {
  songIds: ID[]; // in date-added desc
  albumIds: ID[];
  playlistIds: ID[]; // editorial playlists the user added + own playlists
  artistIds: ID[]; // every artist in the library: followed + derived from saved songs/albums
  followedArtistIds?: ID[]; // explicit follows only (drives the Follow button)
  lovedIds: ID[]; // loved songs/albums/playlists (favorites)
  addedAt: Record<ID, string>;
}

export interface PlayHistoryEntry { songId: ID; playedAt: string; contextType?: ContentType; contextId?: ID }

export interface SearchResults {
  term: string;
  top: ContentItem[];
  songs: Song[];
  albums: Album[];
  artists: Artist[];
  playlists: Playlist[];
  stations: Station[];
}

export interface SearchSuggestion { kind: 'term' | 'content'; term?: string; item?: ContentItem }

export interface ArtistPage {
  artist: Artist;
  latestRelease?: Album;
  topSongs: Song[];
  albums: Album[];
  singlesAndEps: Album[];
  appearsOn: Album[];
  playlists: Playlist[]; // editorial playlists featuring artist
  similarArtists: Artist[];
}

export interface AlbumPage { album: Album; tracks: Song[]; moreByArtist: Album[]; youMightAlsoLike: Album[] }
export interface PlaylistPage { playlist: Playlist; tracks: Song[]; moreLikeThis: Playlist[] }
export interface StationPlayback { station: Station; tracks: Song[] } // next N tracks of an endless station

export interface ApiError { error: { code: string; message: string } }

/**
 * HTTP API (all JSON, prefix /api). Auth via httpOnly cookie "vybe_session".
 * Anonymous users can browse + play; library/playlist/history endpoints need auth (401 otherwise).
 *
 * GET    /api/health                               -> { ok: true }
 * POST   /api/auth/signup  {email,password,displayName} -> { user: User }
 * POST   /api/auth/signin  {email,password}        -> { user: User }
 * POST   /api/auth/signout                         -> { ok: true }
 * GET    /api/auth/me                              -> { user: User | null }
 *
 * GET    /api/pages/home        -> PageResponse   (personalized when signed in: Top Picks, Recently Played, Made For You, ...)
 * GET    /api/pages/new         -> PageResponse   (hero, Best New Songs, New Releases, Updated Playlists, ...)
 * GET    /api/pages/radio       -> PageResponse   (live stations, genre stations, ...)
 * GET    /api/pages/browse-categories -> { genres: Genre[] }   (search landing tiles)
 * GET    /api/genres/:id        -> PageResponse   (category room)
 *
 * GET    /api/songs/:id         -> { song: Song }
 * GET    /api/songs?ids=a,b     -> { songs: Song[] }
 * GET    /api/songs/:id/lyrics  -> { lines: LyricLine[] }   (404 when none)
 * GET    /api/albums/:id        -> AlbumPage
 * GET    /api/artists/:id       -> ArtistPage
 * GET    /api/artists/:id/songs?sort=popularity|date -> { songs: Song[] }
 * GET    /api/playlists/:id     -> PlaylistPage
 * GET    /api/stations/:id/next?count=10&exclude=a,b -> StationPlayback
 * GET    /api/stream/:songId    -> audio/mp4 (AAC), Range support (206), Accept-Ranges: bytes
 * GET    /api/recommendations/autoplay?songId=x&exclude=a,b&count=10 -> { songs: Song[] }  (similar-song "autoplay" continuation)
 *
 * GET    /api/search?term=x&types=songs,albums,artists,playlists,stations&limit=25 -> SearchResults
 * GET    /api/search/suggestions?term=x -> { suggestions: SearchSuggestion[] }
 *
 * GET    /api/me/library                 -> LibraryState
 * PUT    /api/me/library/:type/:id       -> LibraryState   (type: song|album|playlist|artist)  add
 * DELETE /api/me/library/:type/:id       -> LibraryState   remove
 * PUT    /api/me/loves/:type/:id         -> LibraryState   love (also adds to library)
 * DELETE /api/me/loves/:type/:id         -> LibraryState
 * GET    /api/me/library/songs           -> { songs: Song[] }
 * GET    /api/me/library/albums          -> { albums: Album[] }
 * GET    /api/me/library/artists         -> { artists: Artist[] }
 * GET    /api/me/library/playlists       -> { playlists: Playlist[] }
 * GET    /api/me/recently-added          -> { items: ContentItem[] }
 * GET    /api/me/history?limit=50        -> { entries: (PlayHistoryEntry & { song: Song })[] }
 * POST   /api/me/history  {songId, contextType?, contextId?, playedMs} -> { ok: true }
 * POST   /api/me/playlists {name, description?, trackIds?} -> { playlist: Playlist }
 * PATCH  /api/me/playlists/:id {name?, description?, isPublic?, trackIds?} -> { playlist: Playlist }  (trackIds = full reorder/replace)
 * POST   /api/me/playlists/:id/tracks {trackIds, position?} -> { playlist: Playlist }  (append, duplicates allowed)
 * DELETE /api/me/playlists/:id/tracks/:index -> { playlist: Playlist }  (remove by position)
 * DELETE /api/me/playlists/:id   -> { ok: true }
 */
export const API_PREFIX = '/api';

export const GENRE_IDS = ['pop', 'hiphop', 'rnb', 'electronic', 'rock', 'indie', 'jazz', 'classical', 'country', 'latin', 'ambient', 'lofi'] as const;

export const formatDuration = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  return h ? `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}` : `${m}:${String(sec).padStart(2, '0')}`;
};

export const formatLongDuration = (ms: number): string => {
  const min = Math.round(ms / 60000);
  if (min < 60) return `${min} minute${min === 1 ? '' : 's'}`;
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${h} hour${h === 1 ? '' : 's'}${m ? `, ${m} minute${m === 1 ? '' : 's'}` : ''}`;
};
